import{s}from"./auth-Dhq6riO7.js";const a="http://localhost:3001",d=document.querySelector("form"),n=document.getElementById("feedbackText");function c(){const t=document.getElementById("passwd"),o=document.querySelector(".toggle-password");t.type==="password"?(t.type="text",o.innerHTML='<i class="fa-solid fa-eye-slash"></i>'):(t.type="password",o.innerHTML='<i class="fa-regular fa-eye"></i>')}window.togglePassword=c;d.addEventListener("submit",async t=>{t.preventDefault();const o=document.getElementById("user").value,r=document.getElementById("passwd").value;n.textContent="";try{const e=await(await fetch(`${a}/login`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({user:o,passwd:r})})).json();if(e.error){n.textContent=e.error;return}e.token&&s.set("token",e.token),s.set("user",o),s.set("passwd",r),e.rol&&s.set("rol",e.rol),window.location.href=e.redirect}catch{n.textContent="Error del servidor."}});
